    static func lookup(_ language: DisplayLanguage, _ key: StringKey) -> String? {
        switch language {
        case .hanji: hanji[key]
        case .tailo: tailo[key]
        case .poj: poj[key]
        case .system, .japanese, .english: nil
        }
    }
